10	
11	/**
12	 * Runs after {@link ValidateCityCapacity} and before {@link BuildOwner}. A read-only
13	 * validation gate: rejects the create with a 429 when 100 or more owners have already been
14	 * created on the same business day (by {@code registrationDate}), so no more than 100 owners
15	 * can be registered per business day. The business day is this create's effective,
16	 * weekend-adjusted registration date — matching the date {@link BuildOwner} will store — so
17	 * the count buckets owners by adjusted business day. Publishes nothing; it only escalates
18	 * when the limit is reached.
19	 */
20	public class ValidateDailyOwnerLimit {
21	
22	    private static final int DAILY_LIMIT = 100;
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DailyOwnerLimitException {
26	        LocalDate businessDay = BusinessDay.effectiveRegistrationDate(request.getRegistrationDate());
27	        int count = 0;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (businessDay.equals(existing.getRegistrationDate())) {
30	                count++;
31	            }
32	        }
33	        if (count >= DAILY_LIMIT) {
34	            throw new DailyOwnerLimitException(
35	                    DAILY_LIMIT + " or more owners have already been created on this business day");
36	        }
37	    }
38	}
